// Solution: Improve tests, then repair shipping
using System;

static decimal ShippingFee(int units)
{
    if (units <= 0) throw new ArgumentOutOfRangeException(nameof(units));
    return units >= 10 ? 0m : 5m;
}

static void CheckFee(int units, decimal expected)
{
    decimal actual = ShippingFee(units);
    Console.WriteLine($"{(actual == expected ? "PASS" : "FAIL")} fee for {units}: {actual:F2}");
}

static void CheckRejected(int units)
{
    try
    {
        ShippingFee(units);
        Console.WriteLine($"FAIL accepted {units}");
    }
    catch (ArgumentOutOfRangeException)
    {
        Console.WriteLine($"PASS rejected {units}");
    }
}

CheckFee(3, 5m);
CheckFee(12, 0m);
CheckFee(10, 0m);
CheckRejected(0);
CheckRejected(-1);


Against the original candidate, 10 units returns 5.00 instead of zero, and zero and -1 are accepted. The repaired version passes all five checks. Explain why the original two passing examples were insufficient and which evidence would justify accepting the revision. This is practice in reviewing test coverage, not proof that five examples establish every possible behavior.


