% Write a function that sets the values in a given

% rectangular array to 10 \* (row index +1) + column index + 1, with the

% normal row and column indices, starting from 0. For example

% an array with two rows

% and five columns would end up with values below. Your method should set

% the values in the array, not print them out::

% 11 12 13 14 15

% 21 22 23 24 25

% If there are no more than 9 rows or columns, this display gives row and

% column numbers neatly for the normal human counting system, starting from 1.

% .. index:: exercise; varying column width

% varying column width exercise

% .. _varying-width-columns-exercise:

% Varying Column Width Exercise

% ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

% Copy the project file :repsrc:`print_table/print_table.cs` to a file

% :file:`print_varying_width_table.cs` in a project of yours.

% Edit it so that *each* column

% is only as wide as it needs to be: the width for the widest entry in

% that column.

% The earlier data would now print as::

% 2 4  7 55 |  68

% 3 1  8 10 |  22

% 6 0 49 12 |  67

% ----------------

% 11 5 64 77 | 157

% Calculate each of these widths *only once*.

% Hint: Create an array of widths and an array of format strings.

```{index} array; two-dimensional
```

````{dropdown} Complete program: print_table.cs
```csharp
using System;

namespace IntroCS
{
   public class PrintTableExample
   {
      public static void PrintTable()
      {
         int[,] table = { {2, 4,  7, 55},
            {3, 1,  8, 10},
            {6, 0, 49, 12}
         };
         for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 4; c++) {
               Console.Write("{0, 5}", table[r, c]);
            }
            Console.WriteLine();
         }
      }                          //end nested loop chunk

      static void PrintTableAndSums(int[,] t)
      {
         int[] rowSum = new int[t.GetLength(0)],
         colSum = new int[t.GetLength(1)];
         int sum = 0;
         for (int r = 0; r < t.GetLength(0); r++) {
            for (int c = 0; c < t.GetLength(1); c++) {
               rowSum[r] += t[r, c];
               colSum[c] += t[r, c];
            }
            sum += rowSum[r];
         }
         int width = (""+sum).Length;
         foreach (int n in t) {
            width = Math.Max(width, (""+n).Length);
         }
         foreach (int n in colSum) {
            width = Math.Max(width, (""+n).Length);
         }
         foreach (int n in rowSum) {
            width = Math.Max(width, (""+n).Length);
         }
         string format = "{0," + width + "} ";

         for (int r = 0; r < t.GetLength(0); r++) {
            for (int c = 0; c < t.GetLength(1); c++) {
               Console.Write(format, t[r, c]);
            }
            Console.WriteLine("| " + format, rowSum[r]);
         }
         string reps = StringOfReps("-",(width+1)*(t.GetLength(1)+1) + 1);
         Console.WriteLine(reps);
         for (int c = 0; c < t.GetLength(1); c++) {
            Console.Write(format, colSum[c]);
         }
         Console.WriteLine("| " + format, sum);
      }
      // end of print with siums chunk
      /// Return s repeated n times.
      static string StringOfReps(string s, int n)
      {
         string ret = "";
         for (int i = 0; i < n; i++) {
            ret += s;
         }
         return ret;
      }

      public static void Main()
      {
         PrintTable();
         Console.WriteLine();
         int[,] a = { {2, 4,  7, 55},
            {3, 1,  8, 10},
            {6, 0, 49, 12}
         };
         PrintTableAndSums(a);
      }
   }
}
```
````


