// Synthetic stock data; no customer records are used.
string[] lines =
{
    "SKU-1042,12", "SKU-1043,0", "SKU-1044,500",
    "SKU-1045,-1", "SKU-1046,501", "SKU-1047,12x",
    "broken", ",3", "SKU-1048,5,extra"
};

foreach (string line in lines)
{
