SimpleGraph graph = new SimpleGraph();
foreach (string room in new[] { "Lobby", "Hall", "Lab", "Office", "Remote" }) graph.AddVertex(room);
graph.AddEdge("Lobby", "Hall"); graph.AddEdge("Hall", "Lab");
